<?php
namespace App\Http\Controllers;use App\Contracts\ProtectedMediaStorage;use App\Models\Portfolio;
class PortfolioLogoController extends Controller{public function __invoke(Portfolio$p,ProtectedMediaStorage$s){abort_unless($p->status==='published',404);$p->load('owner.flipbookSetting','owner.businessBranding');$f=$p->owner->flipbookSetting;$setting=$f?->apply_to_portfolio?$f:$p->owner->businessBranding;abort_unless($setting?->hasLogo()&&$s->exists($setting->logo_object_key),404);$stream=$s->readStream($setting->logo_object_key);return response()->stream(function()use($stream){fpassthru($stream);fclose($stream);},200,['Content-Type'=>$setting->logo_mime_type,'Content-Length'=>(string)$setting->logo_size_bytes,'Cache-Control'=>'public, max-age=300','X-Content-Type-Options'=>'nosniff']);}}
